var npcId=9300015, maps=[701000000], entries=[[8546, 0, "参鸡汤的材料", ["我就是大当家！什么？我那么有名吗？呵呵。。。参鸡汤是我的拿手好菜。可是我现在材料不够了。你去帮我弄鸡肉30个，百年人参2个，我就马上给你做好。"], "#t4000252#出在鸡身上，#t4031029#在#o9600007#出没的山上。。。\n\n#t4000252# #b#c4000252##k/30\n\n#t4031029# #b#c4031029##k/2\n", ["快去吧，一个都不能少。。。"], {}, []], [8546, 1, "参鸡汤的材料", ["参鸡汤的材料一个都不能少，人参和嫩鸡肉。。。"], "#t4000252#出在鸡身上，#t4031029#在#o9600007#出没的山上。。。\n\n#t4000252# #b#c4000252##k/30\n\n#t4031029# #b#c4031029##k/2\n", ["你还真行！我马上给你做好，等等啊~"], {}, []], [8547, 0, "参鸡汤做好了", ["快做好了，等等。。。好香啊~"], "做好#b参鸡汤#k主要是火候，慢慢熬。。。", ["明明女士一定会很喜欢的。。。 哈哈。。。"], {}, []], [8547, 1, "参鸡汤做好了", ["参鸡汤，火候要适中。。。"], "做好#b参鸡汤#k主要是火候，慢慢熬。。。", ["我的手艺天下闻名，小小参鸡汤算什么哈哈~"], {}, []], [8682, 0, "\u5927\u5f53\u5bb6\u7684\u79c1\u623f\u83dc", ["\u4e00\u5e74\u4e00\u5ea6\u7684\u7279\u7ea7\u53a8\u5e08\u8003\u8bd5\u5c31\u8981\u5f00\u59cb\u4e86\u3002\u8fd9\u6b21\u7684\u9898\u76ee\u662f\u9c7c\u7684\u6599\u7406\uff0c\u65f6\u95f4\u7d27\u8feb\uff0c\u4f46\u8003\u8bd5\u6240\u9700\u7684\u6750\u6599\u6211\u90fd\u8fd8\u6ca1\u6709\u51c6\u5907\u597d\u2026\u8fd9\u8be5\u600e\u4e48\u529e\uff1f\u4f60\u53ef\u4ee5\u5e2e\u5e2e\u6211\u5417\uff1f"], "\u5927\u5f53\u5bb6\u8bf4\u8981\u53bb\u8003\u7279\u7ea7\u53a8\u5e08\uff0c\u4f46\u6750\u6599\u8fd8\u6ca1\u51c6\u5907\u597d\uff0c\u60f3\u8981\u8bf7\u6211\u5e2e\u5fd9\u3002\u4ed6\u8bf4\u4ed6\u8981#r288cm\u7684\u9c91\u9c7c5\u6761\u3001100cm\u7684\u9ca4\u9c7c5\u6761\u30013.6cm\u7684\u94f6\u9c7c5\u6761\u3001131cm\u7684\u65d7\u9c7c5\u6761#k\uff0c\u52a0\u4e0a\u65b0\u7684#r\u9505\u5b50\u8ddf\u94f2\u5b50\u5404\u4e00\u4e2a#k\uff0c\u6211\u8fd9\u5c31\u5feb\u70b9\u53bb\u5e2e\u4ed6\u51c6\u5907\u5427\uff01", ["\u8c22\u8c22\u4f60\uff01\u56e0\u8fd9\u6b21\u7684\u9898\u76ee\u662f\u9c7c\u7684\u6599\u7406\uff0c\u6240\u4ee5\u6211\u9700\u8981#r288cm\u7684\u9c91\u9c7c5\u6761\u3001100cm\u7684\u9ca4\u9c7c5\u6761\u30013.6cm\u7684\u94f6\u9c7c5\u6761\u3001131cm\u7684\u65d7\u9c7c5\u6761#k\u6765\u5236\u4f5c\u6599\u7406\uff0c\u800c\u4e14\u6211\u7684\u9505\u5b50\u8ddf\u94f2\u5b50\u56e0\u4f7f\u7528\u8fc7\u4e45\uff0c\u90fd\u574f\u5dee\u4e0d\u591a\u4e86\uff0c\u56e0\u6b64\u4e5f\u8bf7\u4f60\u5e26\u56de\u65b0\u7684#r\u9505\u5b50\u8ddf\u94f2\u5b50\u5404\u4e00\u4e2a#k\u7ed9\u6211\uff0c\u597d\u8ba9\u6211\u53ef\u4ee5\u5b89\u5fc3\u7684\u53bb\u53c2\u52a0\u8003\u8bd5\uff01\u90a3\u5c31\u62dc\u6258\u4f60\u4e86~"], {}, []], [8682, 1, "\u5927\u5f53\u5bb6\u7684\u79c1\u623f\u83dc", ["\u6211\u7684\u53a8\u827a\u51fa\u795e\u5165\u5316\u3001\u83dc\u80b4\u7684\u4f5c\u6cd5\u8bb2\u7a76\uff0c\u8981\u62ff\u5230\u7279\u7ea7\u53a8\u5e08\u8d44\u683c\u662f\u8f7b\u800c\u4e00\u4e3e\u7684\uff01"], "\u5927\u5f53\u5bb6\u8bf4\u8981\u53bb\u8003\u7279\u7ea7\u53a8\u5e08\uff0c\u4f46\u6750\u6599\u8fd8\u6ca1\u51c6\u5907\u597d\uff0c\u60f3\u8981\u8bf7\u6211\u5e2e\u5fd9\u3002\u4ed6\u8bf4\u4ed6\u8981#r288cm\u7684\u9c91\u9c7c5\u6761\u3001100cm\u7684\u9ca4\u9c7c5\u6761\u30013.6cm\u7684\u94f6\u9c7c5\u6761\u3001131cm\u7684\u65d7\u9c7c5\u6761#k\uff0c\u52a0\u4e0a\u65b0\u7684#r\u9505\u5b50\u8ddf\u94f2\u5b50\u5404\u4e00\u4e2a#k\uff0c\u6211\u8fd9\u5c31\u5feb\u70b9\u53bb\u5e2e\u4ed6\u51c6\u5907\u5427\uff01", ["\u4f60\u5e2e\u6211\u628a\u6750\u6599\u90fd\u62ff\u6765\u5566\uff01\u90a3\u6211\u53ef\u4ee5\u5b89\u5fc3\u53bb\u8003\u8bd5\u4e86\uff0c\u8c22\u8c22\u4f60\uff01\u8fd9\u662f\u6211\u7684\u4e00\u70b9\u5fc3\u610f\u8bf7\u6536\u4e0b\u5427\uff01"], {}, []]], greeting="来来来~排队排队！一个一个来，不要急。";
var choices=[], picked=null, page=0, stage="menu", closed=false, started=false, origin=-1, rewardIndex=-1;
function finish(){closed=true;cm.dispose();}
function validPlace(){
    return cm.getNpc()==npcId && maps.indexOf(cm.getMapId())>=0 && (origin<0 || origin==cm.getMapId());
}
function ready(){
    var q=Packages.server.quest.MapleQuest.getInstance(picked[0]);
    return picked[1]==0 ? q.canStart(cm.getPlayer(),cm.getNpc()) : q.canComplete(cm.getPlayer(),cm.getNpc());
}
function start(){
    if(closed || started)return;
    started=true;
    if(!validPlace()){finish();return;}
    origin=cm.getMapId();
    var menu="";
    for(var i=0;i<entries.length;i++){
        var d=entries[i],q=Packages.server.quest.MapleQuest.getInstance(d[0]);
        if((d[1]==0 && q.canStart(cm.getPlayer(),cm.getNpc())) || (d[1]==1 && cm.getQuestStatus(d[0])==1)){
            menu+="\r\n#L"+choices.length+"#"+(d[1]==0?"[接受] ":"[继续] ")+d[2]+"#l";
            choices.push(d);
        }
    }
    if(choices.length==0){cm.sendOk(greeting+"\r\n\r\n当前没有可以交接的普通任务。");finish();return;}
    cm.sendSimple(greeting+"\r\n"+menu);
}
function showBefore(){
    var text=picked[3][page];
    if(picked[6][String(page)])cm.sendSimple(text);
    else if(page==picked[3].length-1)cm.sendYesNo(text);
    else cm.sendNext(text);
}
function commit(){
    if(!ready()){cm.sendOk(picked[4] || "任务条件尚未完成，请查看任务栏中的要求。");finish();return;}
    if(picked[7].length>0 && rewardIndex<0){
        stage="reward";
        var menu="请选择一件任务奖励：";
        for(var i=0;i<picked[7].length;i++)menu+="\r\n#L"+i+"##i"+picked[7][i][0]+"# #t"+picked[7][i][0]+"# × "+picked[7][i][1]+"#l";
        cm.sendSimple(menu);return;
    }
    closed=true;
    if(picked[7].length>0){
        // Native reward selection is zero based; client rewards here have no job/gender filters.
        var q=Packages.server.quest.MapleQuest.getInstance(picked[0]);
        var player=cm.getPlayer(),npc=cm.getNpc(),client=cm.getClient();
        cm.dispose();client.removeClickedNPC();
        q.complete(player,npc,java.lang.Integer.valueOf(rewardIndex),false);
    }else if(picked[1]==0)cm.startClientNpcQuest(picked[0]);
    else cm.completeClientNpcQuest(picked[0]);
}
function accepted(){
    if(picked[5].length==0){commit();return;}
    stage="after";page=0;cm.sendNext(picked[5][page]);
}
function action(mode,type,selection){
    if(closed)return;
    if(!validPlace() || mode!=1){finish();return;}
    if(stage=="menu"){
        if(selection<0 || selection>=choices.length || selection!=Math.floor(selection)){finish();return;}
        picked=choices[selection];
        if(!ready()){cm.sendOk(picked[4] || "任务条件尚未完成，请查看任务栏中的要求。");finish();return;}
        stage="before";page=0;showBefore();return;
    }
    if(stage=="before"){
        var answer=picked[6][String(page)];
        if(answer){
            if(answer.options.indexOf(selection)<0){finish();return;}
            if(selection!=answer.correct){
                if(answer.wrong.length>0)cm.sendOk(answer.wrong.join("\r\n"));
                finish();return;
            }
        }
        if(page<picked[3].length-1){page++;showBefore();return;}
        if(answer){stage="confirm";cm.sendYesNo(picked[2]);return;}
        accepted();return;
    }
    if(stage=="confirm"){accepted();return;}
    if(stage=="reward"){
        if(selection<0 || selection>=picked[7].length || selection!=Math.floor(selection)){finish();return;}
        rewardIndex=selection;commit();return;
    }
    if(stage=="after"){
        if(page<picked[5].length-1){page++;cm.sendNext(picked[5][page]);return;}
        commit();
    }
}
